// Create a flow
fun countDown(from: Int): Flow<Int> = flow {
    for (i in from downTo 0) {
        delay(1000)
        emit(i)  // send value downstream
    }
}

// Collect it (terminal operator)
viewModelScope.launch {
    countDown(5).collect { value ->
        println(value)  // 5, 4, 3, 2, 1, 0
    }
}

// StateFlow — always has a value
private val _count = MutableStateFlow(0)
val count: StateFlow<Int> = _count.asStateFlow()

fun increment() { _count.update { it + 1 } }

// SharedFlow — for one-shot events
private val _events = MutableSharedFlow<UiEvent>()
val events: SharedFlow<UiEvent> = _events.asSharedFlow()

suspend fun showError(msg: String) {
    _events.emit(UiEvent.ShowSnackbar(msg))
}

// Collecting StateFlow in Compose
val count by viewModel.count.collectAsState()

// Search with debounce + flatMapLatest
searchQuery
    .debounce(300)           // wait 300ms after typing stops
    .filter { it.length > 2 } // ignore short queries
    .flatMapLatest { query ->
        repository.search(query) // cancel previous search
    }
    .collect { results -> _state.update { it.copy(results = results) } }

// Combine multiple flows
combine(userFlow, settingsFlow) { user, settings ->
    UiState(user = user, darkMode = settings.darkMode)
}.collect { state -> _uiState.value = state }
